1	//! Agent-facing output: TOON projections of command results and conversion of [`MonoklError`] into michi errors.
2	use std::collections::BTreeMap;
3	
4	use camino::Utf8Path;
5	use michi::toon::Value;
6	
7	use crate::error::MonoklError;
8	use crate::types::{Diagnostic, RankedBlock, SearchResponse};
9	
10	/// Maps `None` to [`Value::Null`], so a reader can tell an absent field from an empty string.
11	fn opt_cell(s: Option<&str>) -> Value {
12	    s.map_or(Value::Null, Value::from)
13	}
14	
15	/// The most snippet lines a row can show, and the largest value `--snippet-lines` takes.
16	pub const MAX_SNIPPET_LINES: usize = 3;
17	/// The snippet lines a row shows unless `--snippet-lines` says otherwise.
18	pub const DEFAULT_SNIPPET_LINES: usize = 1;
19	/// The most characters of one matching line a snippet shows.
20	const SNIPPET_LINE_CHARS: usize = 160;
21	
22	/// How a search response is shown: how long each row's snippet is, and the row cap the truncation hint names.
23	///
24	/// # Examples
25	///
26	/// ```
27	/// use monokl::output::agent::SearchView;
28	///
29	/// let view = SearchView::default();
30	/// assert_eq!((view.snippet_lines, view.max_results), (1, 20));
31	/// ```
32	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
33	pub struct SearchView {
34	    /// The most matching lines a row's snippet shows, from 0 to [`MAX_SNIPPET_LINES`]. With 0 the column is `null` and a
35	    /// variable or type alias row, which has no signature, shows no declaration text.
36	    pub snippet_lines: usize,
37	    /// The row cap the response was budgeted with, which tells the hint whether the rows or the tokens ran out.
38	    pub max_results: usize,
39	}
40	
41	impl Default for SearchView {
42	    fn default() -> Self {
43	        Self { snippet_lines: DEFAULT_SNIPPET_LINES, max_results: crate::budget::Budget::default().max_results }
44	    }
45	}
46	
47	/// The lines of `block` that matched the query, numbered, so a reader often needs no second read of the file.
48	///
49	/// A line the signature column already shows is left out: one whose text lies inside the block's
50	/// [`signature_span`](crate::types::CodeBlock::signature_span), except that a Rust `where` clause is not shown in the
51	/// column (see [`signature_cell`]), so the lines of the clause after the declaration line stay. A variable or type
52	/// alias has no signature, so its first line is the best thing to show; so is a first line that says more than the
53	/// signature, such as a decorator or the start of an arrow function's body. A comment or attribute line (a Rust doc
54	/// comment above the declaration, a `#[...]` attribute, a comment in a body) and a where-clause line say less about the
55	/// code than a body line does, so a code line that matched is shown first and those fill the snippet only when there
56	/// are not enough code lines, or are the only match. At most `max_lines` lines appear, in the order they have in the block, each cut to [`SNIPPET_LINE_CHARS`]
57	/// characters, and the lines beyond that are counted, not dropped silently. With `max_lines` 0 there is no snippet.
58	fn snippet(block: &crate::types::CodeBlock, max_lines: usize) -> Option<String> {
59	    let mut lines = Vec::new();
60	    let mut start = block.span.start;
61	    for text in block.code.split('\n') {
62	        lines.push((start, text));
63	        start += text.len() + 1;
64	    }
65	    let where_at = block.where_start;
66	    let mut shown: Vec<usize> = block
67	        .matched_lines
68	        .iter()
69	        .copied()
70	        .filter(|&line| line >= block.line_start && line - block.line_start < lines.len())
71	        .filter(|&line| {
72	            let (start, text) = lines[line - block.line_start];
73	            !block.signature_span.as_ref().is_some_and(|head| inside(head, start, text))
74	                || where_at.is_some_and(|at| start + (text.len() - text.trim_start().len()) >= at)
75	        })
76	        .collect();
77	    shown.sort_unstable();
78	    shown.dedup();
79	    let hidden = shown.len().saturating_sub(max_lines);
80	    // Stable, so each kind of line stays in block order; the chosen lines are put back in block order.
81	    shown.sort_by_key(|&line| {
82	        let (start, text) = lines[line - block.line_start];
83	        let content_start = start + (text.len() - text.trim_start().len());
84	        let in_where_clause = where_at.is_some_and(|at| content_start >= at)
85	            && block.signature_span.as_ref().is_some_and(|head| content_start < head.end);
86	        is_comment_or_attribute(text) || in_where_clause
87	    });
88	    shown.truncate(max_lines);
89	    shown.sort_unstable();
90	    let mut out: Vec<String> = shown
91	        .iter()
92	        .map(|&line| {
93	            let text = lines[line - block.line_start].1.trim();
94	            let mut chars = text.chars();
95	            let head: String = chars.by_ref().take(SNIPPET_LINE_CHARS).collect();
96	            let ellipsis = if chars.next().is_some() { "…" } else { "" };
97	            format!("{line}: {head}{ellipsis}")
98	        })
99	        .collect();
100	    if out.is_empty() {
101	        return None;
102	    }
103	    if hidden > 0 {
104	        out.push(format!("+{hidden} more"));
105	    }
106	    Some(out.join("\n"))
107	}
108	
109	/// The `symbolSignature` cell. A Rust signature ends where its where clause starts, with ` where …` to say there is one:
110	/// the clause is a list of bounds that is often longer than the rest of the signature, and the row's snippet shows a
111	/// line of it when that line matched. The clause is where the analyzer recorded it in
112	/// [`where_start`](crate::types::CodeBlock::where_start), so a `where` inside a comment or a literal is not mistaken for
113	/// it; the ranking still reads the whole signature.
114	fn signature_cell(block: &crate::types::CodeBlock) -> Option<String> {
115	    let signature = block.symbol_signature.as_deref()?;
116	    let before_clause = block.signature_span.as_ref().zip(block.where_start).and_then(|(head, at)| {
117	        let offset = |position: usize| position.checked_sub(block.span.start);
118	        block.code.get(offset(head.start)?..offset(at)?)
119	    });
120	    Some(match before_clause {
121	        Some(text) => format!("{} where …", text.split_whitespace().collect::<Vec<_>>().join(" ")),
122	        None => signature.to_owned(),
123	    })
124	}
125	
126	/// Whether a line looks like only a comment or an attribute: it starts with `//`, `/*`, `*/`, `* ` (the body of a block
127	/// comment), `#[` or `#![`. A line that starts with `*` and no space is code (a dereference), as is any other.
128	///
129	/// This reads the line's text, not the syntax tree, because it only orders the lines of a snippet: a line wrongly taken
130	/// for a comment (one that begins `//` inside a multi-line string) is shown after the other matched lines instead of
131	/// before them, and is never left out, so a wrong answer costs a less useful snippet line and no information.
132	fn is_comment_or_attribute(text: &str) -> bool {
133	    let text = text.trim_start();
134	    ["//", "/*", "*/", "#[", "#!["].iter().any(|prefix| text.starts_with(prefix))
135	        || text == "*"
136	        || text.starts_with("* ")
137	}
138	
139	/// Whether the text of a line, which starts at byte `start`, holds something and lies wholly inside `head`.
140	fn inside(head: &std::ops::Range<usize>, start: usize, text: &str) -> bool {
141	    let content = text.trim();
142	    let content_start = start + (text.len() - text.trim_start().len());
143	    !content.is_empty() && head.start <= content_start && content_start + content.len() <= head.end
144	}
145	
146	/// The `parent` cell: the kind and name of the block's parent, such as `class Foo` for a method; `null` for a
147	/// top-level block.
148	fn parent_cell(parent: Option<&crate::types::ParentContext>) -> Value {
149	    opt_cell(parent.map(|p| format!("{} {}", p.kind.as_str(), p.name)).as_deref())
150	}
151	
152	fn search_row(block: &crate::types::RankedBlock, snippet_lines: usize) -> [Value; 9] {
153	    [
154	        Value::from(block.block.file.as_str()),
155	        Value::from(block.block.line_start),
156	        Value::from(block.block.line_end),
157	        Value::from(block.block.node_kind.as_str()),
158	        parent_cell(block.block.parent.as_ref()),
159	        opt_cell(signature_cell(&block.block).as_deref()),
160	        opt_cell(snippet(&block.block, snippet_lines).as_deref()),
161	        Value::from(block.rank),
162	        Value::from(block.final_score),
163	    ]
164	}
165	
166	const SEARCH_FIELDS: [&str; 9] =
167	    ["file", "lineStart", "lineEnd", "nodeKind", "parent", "symbolSignature", "snippet", "rank", "finalScore"];
168	
169	/// The line `monokl search` prints for each of `blocks`, indentation included and the newline left out.
170	///
171	/// The search budget measures these lines, so a cap counts what the reader receives. Rendering them in one table keeps
172	/// michi's cell quoting and truncation as the only definition of a row.
173	pub fn search_row_texts(blocks: &[RankedBlock], snippet_lines: usize) -> Vec<String> {
174	    let rows: Vec<Vec<Value>> = blocks.iter().map(|block| search_row(block, snippet_lines).to_vec()).collect();
175	    let rendered = michi::AgentResponse::new("search").items(rows, SEARCH_FIELDS.as_slice()).render_toon();
176	    rendered.lines().skip(1).map(str::to_owned).collect()
177	}
178	
179	/// Renders a search response as a TOON table of its rows, followed by the truncation count and hints.
180	pub fn render_search(response: &SearchResponse, view: &SearchView) -> String {
181	    let rows: Vec<Vec<Value>> =
182	        response.results.iter().map(|block| search_row(block, view.snippet_lines).to_vec()).collect();
183	    let mut rendered =
184	        michi::AgentResponse::new("search").items(rows, SEARCH_FIELDS.as_slice()).hints(search_hints(response, view));
185	    if response.truncated {
186	        rendered = rendered.total_count(response.total_blocks_before_truncation);
187	    }
188	    rendered.render_toon()
189	}
190	
191	/// What the truncation hint tells a reader to do to see more.
192	///
193	/// Rows the caps left out are reached with `--offset`, which names the exact next value so the reader does not pay for
194	/// the rows already seen; rows the relevance cut dropped are reached with `--min-score 0`, which keeps the same order,
195	/// so the same offsets still apply. An offset past the last kept row says so and how many rows there are. The caps are
196	/// named only when a page came back empty, because an offset would not move past a row that does not fit.
197	fn truncation_guidance(response: &SearchResponse, view: &SearchView) -> String {
198	    let returned = response.results.len();
199	    let cut = response.blocks_cut_by_relevance;
200	    let relevant = response.total_blocks_before_truncation.saturating_sub(cut);
201	    let left = relevant.saturating_sub(response.offset + returned);
202	    let below_cut = (cut > 0)
203	        .then(|| format!("--min-score 0 for the {cut} {} below the cut", if cut == 1 { "row" } else { "rows" }));
204	    let mut parts = Vec::new();
205	    if returned == 0 && response.offset >= relevant {
206	        parts.push(format!("offset {} is past the last of {relevant} rows", response.offset));
207	        parts.extend(below_cut);
208	        return parts.join("; ");
209	    }
210	    if left > 0 && returned > 0 {
211	        parts.push(format!("next: --offset {}", response.offset + returned));
212	    } else if left > 0 {
213	        parts.push(format!(
214	            "{} for more",
215	            if returned >= view.max_results { "--max-results N" } else { "--max-tokens N" }
216	        ));
217	    }
218	    parts.extend(below_cut);
219	    parts.push("refine with +term/-term".to_owned());
220	    let (last, rest) = parts.split_last().map_or(("", &[][..]), |(last, rest)| (last.as_str(), rest));
221	    if rest.is_empty() { last.to_owned() } else { format!("{}, or {last}", rest.join(", ")) }
222	}
223	
224	fn search_hints(response: &SearchResponse, view: &SearchView) -> Vec<michi::Hint> {
225	    let shown =
226	        michi::TruncationOutcome::new(response.results.iter().collect(), response.total_blocks_before_truncation);
227	    let mut hints: Vec<michi::Hint> = shown.hint(truncation_guidance(response, view)).into_iter().collect();
228	    hints.extend(diagnostic_lines(&response.diagnostics).into_iter().map(michi::Hint::new));
229	    let past_the_end = response.offset > 0 && response.total_blocks_before_truncation > 0;
230	    if response.results.is_empty() && !past_the_end {
231	        hints.push(michi::Hint::new(
232	            "only declarations and the members of their classes, objects, impls and traits are searched; for text in tests, calls or config try rg",
233	        ));
234	    }
235	    hints
236	}
