314	    #[test]
315	    fn a_snippet_shows_matching_lines_with_their_numbers_but_not_the_signature_line() {
316	        let b = block(10, "function f() {\n  const price = 1;\n  return price;\n}", &[10, 11, 12]);
317	        assert_eq!(snippet(&b), Some("11: const price = 1;\n12: return price;".to_owned()));
318	    }
