344	    #[test]
345	    fn a_first_line_that_says_more_than_the_head_is_shown() {
346	        let b = headed(2, "load = () => needle(\n  1,\n);", "load = () => ", &[2]);
347	        assert_eq!(snippet(&b), Some("2: load = () => needle(".to_owned()));
