392	    fn a_code_line_is_shown_before_a_doc_comment_that_matched() {
393	        let code = "/// needle docs\npub fn f() {\n    needle();\n}";
394	        let b = headed(7, code, "pub fn f() {", &[7, 9]);
395	        assert_eq!(snippet_of(&b, 1), Some("9: needle();\n+1 more".to_owned()));
