406	    fn an_attribute_line_is_shown_after_the_code_lines_that_matched() {
407	        let code = "#[needle]\npub fn f() {\n    needle();\n}";
408	        let b = headed(3, code, "pub fn f() {", &[3, 5]);
409	        assert_eq!(snippet_of(&b, 1), Some("5: needle();\n+1 more".to_owned()));
410	        let only = headed(3, code, "pub fn f() {", &[3]);
411	        assert_eq!(snippet_of(&only, 1), Some("3: #[needle]".to_owned()));
