414	    #[test]
415	    fn every_comment_form_gives_way_to_a_code_line() {
416	        for comment in
417	            ["// needle", "//! needle", "/// needle", "/* needle */", "/** needle */", "* needle", "*/", "#![needle]"]
418	        {
419	            let code = format!("function f() {{\n  {comment}\n  needle();\n}}");
420	            let b = block(1, &code, &[2, 3]);
