426	    fn a_dereference_or_a_multiplication_is_code_not_a_comment() {
427	        for line in ["*ptr = needle;", "**ptr = needle;", "#needle = 1;", "@Dec(needle)"] {
428	            let code = format!("function f() {{\n  {line}\n}}");
429	            let b = block(1, &code, &[2]);
