436	    #[test]
437	    fn the_lines_a_snippet_shows_keep_their_order_in_the_block_with_code_lines_chosen_first() {
438	        let b = block(1, "head\n// c1\nx1\n// c2\nx2\nx3", &[2, 3, 4, 5, 6]);
439	        assert_eq!(snippet_of(&b, 3), Some("3: x1\n5: x2\n6: x3\n+2 more".to_owned()));
