1053	    use michi::ErrorCode;
1054	    match kind {
1055	        std::io::ErrorKind::NotFound => ErrorCode::NotFound,
1056	        std::io::ErrorKind::PermissionDenied => ErrorCode::Forbidden,
1057	        std::io::ErrorKind::NotADirectory => ErrorCode::InvalidInput,
1058	        _ => ErrorCode::ExternalFailure,
1059	    }
