1062	/// Classifies a walk error: an I/O failure by its kind, a bad glob as invalid input, anything else as external.
1063	fn walk_error_code(source: &ignore::Error) -> michi::ErrorCode {
1064	    match source.io_error() {
1065	        Some(io_err) => io_error_code(io_err.kind()),
1066	        None if matches!(source, ignore::Error::Glob { .. }) => michi::ErrorCode::InvalidInput,
1067	        None => michi::ErrorCode::ExternalFailure,
1068	    }
1069	}
