1106	/// Converts an error into a [`michi::DomainError`] for agent output.
1107	pub trait ToDomainError {
1108	    /// Returns a short `snake_case` code that is distinct for each error kind.
1109	    fn monokl_code(&self) -> &'static str;
1110	    /// Converts the error, prefixing the message with [`monokl_code`](Self::monokl_code) and carrying its source chain
1111	    /// as causes.
1112	    fn to_domain_error(&self) -> michi::DomainError;
1113	}
1114	
1115	impl ToDomainError for MonoklError {
1116	    fn monokl_code(&self) -> &'static str {
1117	        match self {
1118	            MonoklError::Io(_) => "io",
1119	            MonoklError::Walk { .. } => "walk",
1120	            MonoklError::RegexBuild(_) => "regex_build",
1121	            MonoklError::NonUtf8Path { .. } => "non_utf8_path",
1122	            MonoklError::TooManyTerms { .. } => "too_many_terms",
1123	        }
1124	    }
1125	
1126	    fn to_domain_error(&self) -> michi::DomainError {
1127	        use michi::ErrorCode;
1128	
1129	        let code = match self {
1130	            MonoklError::RegexBuild(_) | MonoklError::NonUtf8Path { .. } | MonoklError::TooManyTerms { .. } => {
1131	                ErrorCode::InvalidInput
1132	            }
1133	            MonoklError::Io(err) => io_error_code(err.io_kind()),
1134	            MonoklError::Walk { source, .. } => walk_error_code(source),
1135	        };
1136	
1137	        let mut domain_err = michi::DomainError::from_error(code, self).retryable(false);
1138	        // Prefixed after from_error, which compares each cause against the unprefixed message to skip repeats.
1139	        domain_err.message = format!("{}: {}", self.monokl_code(), domain_err.message);
1140	
1141	        domain_err = match self {
1142	            MonoklError::TooManyTerms { count, limit } => {
1143	                domain_err.hint(format!("you supplied {count} terms; the limit is {limit}"))
1144	            }
1145	            MonoklError::Io(_)
1146	            | MonoklError::Walk { .. }
1147	            | MonoklError::RegexBuild(_)
1148	            | MonoklError::NonUtf8Path { .. } => domain_err,
1149	        };
1150	
1151	        domain_err
1152	    }
1153	}
