             src/f1.rs,1,2,function,null,null,null,1,0.5\n  \
             src/f2.rs,2,3,function,null,null,null,2,0.5\n\
             totalCount: 3\n\
             help[1]: \"showing 2 of 3; next: --offset 2, or refine with +term/-term\""
        );
