/// The search command's response.
#[derive(Debug, Clone)]
pub struct SearchResponse {
    pub results: Vec<RankedBlock>,
    pub total_blocks_before_truncation: usize,
    /// How many of the blocks left out of `results` the relevance cut dropped; the row and token caps dropped the rest.
    pub blocks_cut_by_relevance: usize,
    /// How many rows that passed the relevance cut were skipped before `results` starts: the page offset asked for.
    pub offset: usize,
    pub truncated: bool,
    pub diagnostics: Vec<Diagnostic>,
}
    /// Searches hidden files and files that .gitignore or .ignore (in the search path or its parents) would exclude.
    #[arg(long)]
    no_ignore: bool,
    /// Searches only this language: typescript, javascript or rust.
    #[arg(long, value_enum)]
    language: Option<Language>,
    /// The most results to print. It also caps the rows `--min-score` keeps, so it can cut below the first eight.
    #[arg(long, default_value_t = Budget::default().max_results)]
    max_results: usize,
    /// Skips this many ranked rows and prints the next page under the same cut and caps. The relevance cut still
    /// measures against the top row of the whole result; an offset past the last row prints no rows and exits 0.
    #[arg(long, value_name = "N", default_value_t = Budget::default().offset)]
    offset: usize,
    /// The most estimated tokens (one per three bytes) across the printed rows.
    #[arg(long, default_value_t = Budget::default().max_tokens)]
    max_tokens: usize,
    /// Drops the rows scoring below this fraction of the top row's score, but never one of the first eight. 0 keeps every
    /// row up to `--max-results`; 1 keeps only the rows that tie with the top.
    #[arg(long, value_name = "FRACTION", default_value_t = Budget::default().min_score, value_parser = parse_min_score)]
    min_score: f64,
    /// The most matching lines each row's snippet shows, 0 to 3; the rest are counted. 0 prints no snippet, so a
    /// variable or type row, which has no signature, shows no declaration text.
    #[arg(long, value_name = "N", default_value_t = DEFAULT_SNIPPET_LINES, value_parser = parse_snippet_lines)]
    snippet_lines: usize,
    /// Stops after this many seconds and prints what was found so far, marked as a partial result. 0 means no limit.
    #[arg(long, value_name = "SECONDS", default_value = "30", value_parser = parse_timeout)]
    timeout: f64,
}

/// Reads `--timeout`: a non-negative number of seconds, fractions allowed.
fn parse_timeout(text: &str) -> Result<f64, String> {
    let seconds: f64 = text.parse().map_err(|e| format!("`{text}` is not a number of seconds: {e}"))?;
    Duration::try_from_secs_f64(seconds)
        .map(|_| seconds)
        .map_err(|e| format!("`{text}` is not a usable number of seconds: {e}"))
}

/// Reads `--min-score`: a share of the top score, from 0 to 1.
fn parse_min_score(text: &str) -> Result<f64, String> {
    let fraction: f64 = text.parse().map_err(|e| format!("`{text}` is not a fraction: {e}"))?;
    if (0.0..=1.0).contains(&fraction) { Ok(fraction) } else { Err(format!("`{text}` is not between 0 and 1")) }
}

/// Reads `--snippet-lines`: a count from 0 to [`MAX_SNIPPET_LINES`].
fn parse_snippet_lines(text: &str) -> Result<usize, String> {
    let lines: usize = text.parse().map_err(|e| format!("`{text}` is not a number of lines: {e}"))?;
    fn the_estimate_counts_bytes_not_characters() {
        // Eight characters, twenty-four bytes.
        assert_eq!(count_tokens("日本語のコメント"), 8);
    }

    #[test]
    fn a_long_unbroken_run_is_counted_at_once() {
        let text = "a".repeat(200 * 1024);
        assert_eq!(count_tokens(&text), 200 * 1024 / 3 + 1);
    }

    /// The ranks the page at `offset` holds, under the default relevance cut and a row cap of `max_results`.
    fn page(scores: &[f64], offset: usize, max_results: usize) -> SearchResponse {
        let ranked = scored(scores);
        let total = ranked.len();
        let texts: Vec<String> = ranked.iter().map(|b| b.block.code.clone()).collect();
        let budget = Budget { max_results, offset, ..Budget::default() };
        apply_budget(ranked, total, &budget, &texts, Vec::new())
    }

    #[test]
    fn an_offset_skips_that_many_ranked_rows_and_the_next_page_follows_the_first() {
        let scores = [1.0; 31];
        let first = page(&scores, 0, 8);
        let second = page(&scores, 8, 8);
        assert_eq!((ranks(&first), first.offset, first.total_blocks_before_truncation), (one_to(8), 0, 31));
        assert_eq!(ranks(&second), (9..=16).collect::<Vec<_>>());
        assert_eq!((second.offset, second.total_blocks_before_truncation, second.truncated), (8, 31, true));
    }

    #[test]
    fn pages_laid_end_to_end_are_the_one_large_run() {
        let scores = then(&[1.0; 12], 0.5, 19);
        let whole = ranks(&page(&scores, 0, 100));
        let mut paged = Vec::new();
        for offset in (0..scores.len()).step_by(7) {
