        assert_eq!(
            texts,
            [
                "  src/f1.rs,1,2,function,null,null,null,100",
                "  src/f2.rs,2,3,function,null,null,null,50",
                "  src/f3.rs,3,4,function,null,null,null,33",
            ]
        );
