        assert_eq!(printed, texts);
    }

    #[test]
    fn the_rows_the_cut_drops_show_a_relevance_below_the_cut() {
        let scores = [vec![1.0; 8], vec![0.31, 0.29, 0.1]].concat();
        let ranked = scored_blocks(&scores);
