1	//! Black-box tests: run the built `monokl` binary against the `small-ts` fixture project.
2	#![cfg(feature = "cli")]
3	#![allow(clippy::unwrap_used, clippy::expect_used, reason = "a failing assertion should panic in a test")]
4	
5	use std::path::{Path, PathBuf};
6	use std::process::{Command, Output};
7	
8	fn fixture() -> PathBuf {
9	    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/small-ts")
10	}
11	
12	/// Runs `monokl` with the fixture as the working directory, so printed paths are relative.
13	fn monokl(args: &[&str]) -> Output {
14	    Command::new(env!("CARGO_BIN_EXE_monokl")).args(args).current_dir(fixture()).output().unwrap()
15	}
16	
17	fn stdout(output: &Output) -> String {
18	    String::from_utf8(output.stdout.clone()).unwrap()
19	}
20	
21	fn stderr(output: &Output) -> String {
22	    String::from_utf8(output.stderr.clone()).unwrap()
23	}
24	
25	#[test]
26	fn search_prints_ranked_blocks_with_relative_paths() {
27	    let output = monokl(&["search", "format", "."]);
28	    assert!(output.status.success(), "stderr: {}", stderr(&output));
29	    let text = stdout(&output);
30	    let mut lines = text.lines();
31	    assert_eq!(
32	        lines.next(),
33	        Some("search[3]{file,lineStart,lineEnd,nodeKind,parent,symbolSignature,snippet,rank,finalScore}:")
34	    );
35	    let first = lines.next().unwrap();
36	    assert!(
37	        first.starts_with(
38	            "  src/utils/format.ts,1,3,function,null,\"function formatCurrency(amount: number, currency: string = 'USD'): string\",\"2: return new Intl.NumberFormat('en-US', { style: 'currency', currency }).format(amount);\",1,"
39	        ),
40	        "got: {first}"
41	    );
42	    assert!(text.lines().skip(1).all(|line| !line.trim_start().starts_with('/')), "paths should be relative: {text}");
43	}
44	
45	#[test]
46	fn a_row_shows_the_matching_lines_inside_its_block_and_nothing_else() {
47	    let output = monokl(&["search", "format price", "src/", "--max-results", "3", "--snippet-lines", "3"]);
48	    assert!(output.status.success(), "stderr: {}", stderr(&output));
49	    let text = stdout(&output);
50	    let rows: Vec<&str> = text.lines().skip(1).take(3).collect();
51	    assert_eq!(
52	        rows[1],
53	        "  src/utils/validation.ts,8,12,function,null,\"function validatePrice(price: number): ValidationResult\",\
54	         \"9: if (price < 0) return { valid: false, message: 'Price cannot be negative' };\\n\
55	         10: if (price > 1_000_000) return { valid: false, message: formatCurrency(1_000_000) + ' is the maximum' };\",2,4.151139"
56	    );
57	    assert_eq!(
58	        rows[2],
59	        "  src/index.ts,3,3,other,null,null,\"3: export { formatCurrency, truncateString } from './utils/format';\",3,1.345138"
60	    );
61	}
62	
63	#[test]
64	fn search_is_deterministic() {
65	    assert_eq!(stdout(&monokl(&["search", "price", "."])), stdout(&monokl(&["search", "price", "."])));
66	}
67	
68	#[test]
69	fn search_honours_the_result_cap_and_says_so() {
70	    let output = monokl(&["search", "price", ".", "--max-results", "2"]);
71	    let text = stdout(&output);
72	    assert!(text.starts_with("search[2]"), "got: {text}");
73	    assert!(text.contains("totalCount: 8"), "got: {text}");
74	    assert!(text.contains("showing 2 of 8"), "got: {text}");
75	}
76	
77	#[test]
78	fn excluded_terms_remove_files() {
79	    let with = stdout(&monokl(&["search", "price", "."]));
80	    let without = stdout(&monokl(&["search", "price -validation", "."]));
81	    assert!(with.contains("src/utils/validation.ts"));
82	    assert!(!without.contains("src/utils/validation.ts"));
83	}
84	
85	#[test]
86	fn a_query_with_no_match_prints_an_empty_result() {
87	    let output = monokl(&["search", "zzzqqqxx", "."]);
88	    assert!(output.status.success());
89	    assert!(stdout(&output).starts_with("search: []"), "got: {}", stdout(&output));
90	}
91	
92	#[test]
93	fn a_query_that_matches_no_file_of_a_populated_tree_exits_zero_with_the_empty_result() {
94	    let dir = tempfile::tempdir().unwrap();
95	    std::fs::write(dir.path().join("a.ts"), "export const alpha = 1;\n").unwrap();
96	    let output = monokl_in(dir.path(), &["search", "zzzqqqxx", "."]);
97	    assert_eq!(output.status.code(), Some(0), "stderr: {}", stderr(&output));
98	    assert!(stdout(&output).starts_with("search: []\n"), "got: {}", stdout(&output));
99	    assert!(!stdout(&output).contains("totalCount"), "got: {}", stdout(&output));
100	    assert_eq!(stderr(&output), "");
101	}
102	
103	#[test]
104	fn an_invalid_regex_fails_with_a_structured_error() {
105	    let output = monokl(&["search", "regex:(", "."]);
106	    assert_eq!(output.status.code(), Some(1));
107	    assert_eq!(stdout(&output), "");
108	    assert!(stderr(&output).starts_with("error: invalid_input"), "got: {}", stderr(&output));
109	    assert!(stderr(&output).contains("regex_build"), "got: {}", stderr(&output));
110	}
111	
112	#[test]
113	fn a_deeply_nested_file_is_searched_like_any_other() {
114	    let dir = tempfile::tempdir().unwrap();
115	    let nested = format!("export const needle = /'/;\nexport const x = {}1{};\n", "(".repeat(1000), ")".repeat(1000));
116	    std::fs::write(dir.path().join("nested.ts"), nested).unwrap();
117	    std::fs::write(dir.path().join("normal.ts"), "export function needle() {}\n").unwrap();
118	
119	    let output =
120	        Command::new(env!("CARGO_BIN_EXE_monokl")).args(["search", "needle", "."]).current_dir(&dir).output().unwrap();
121	
122	    assert_eq!(output.status.code(), Some(0), "stderr: {}", stderr(&output));
123	    let text = stdout(&output);
124	    let lines: Vec<&str> = text.lines().take(3).collect();
125	    assert_eq!(lines[0], "search[2]{file,lineStart,lineEnd,nodeKind,parent,symbolSignature,snippet,rank,finalScore}:");
126	    assert!(lines[1].starts_with("  normal.ts,1,1,function,null,function needle(),null,1,"), "got: {text}");
127	    assert!(
128	        lines[2].starts_with("  nested.ts,1,1,variable,null,null,\"1: export const needle = /'/;\",2,"),
129	        "got: {text}"
130	    );
131	}
132	
133	#[test]
134	fn a_file_nested_past_the_cap_is_skipped_and_reported_while_the_others_are_searched() {
