    assert_eq!(found, [("const needle = 2;", vec![1])]);
}

fn found(result: &SearchResult) -> Vec<(usize, usize, Vec<usize>)> {
    let mut found: Vec<_> =
        result.ranked.iter().map(|r| (r.block.line_start, r.block.line_end, r.block.matched_lines.clone())).collect();
    found.sort();
    found
}

